<template>
  <div class="publicPage">
    <div class="publicPage-content">
      <div class="content-left">
        <el-button @click="getContent"> 获取内容(console) </el-button>
        <el-button @click="showDialog"> 预览 </el-button>
      </div>

      <div class="content-right">
        <div class="content-right-editor">
          <UEditorPlus
            ref="editor"
            class="editor"
            v-model="richObj.content"
            :height="editorHeight"
            :configs="editorConfigs"
          ></UEditorPlus>
        </div>
      </div>
    </div>

    <el-dialog
      title="提示"
      :visible.sync="dialogVisible"
      width="60%"
      :before-close="hideDialog"
    >
      <div v-html="richObj.content"></div>
    </el-dialog>
  </div>
</template>

<script>
import UEditorPlus from "@/components/UEditorPlus/index.vue";

export default {
  name: "publicPage",
  components: { UEditorPlus },
  props: {
    passData: {
      type: Object,
      default: () => {
        return {};
      },
    },
  },
  watch: {
    passData(val) {
      this.getDetail(val);
    },
  },
  dicts: [],
  data() {
    return {
      richObj: {},
      editorHeight: 0,
      dialogVisible: false,
      customContent: require("./demoContent.json"),
      editorConfigs: {
        readonly: true, // 是否禁用
      },
    };
  },
  methods: {
    getDetail(data) {
      this.$nextTick(() => {
        this.richObj = data;
      });
    },

    initEditorHeight() {
      let dom = document.querySelector(".publicPage-content");
      this.$nextTick(() => {
        this.editorHeight = dom.clientHeight - 148;
        this.$refs.editor.reSetEditorHeight(this.editorHeight);
      });
    },

    getContent() {
      console.log(this.richObj.content);
    },

    showDialog() {
      this.dialogVisible = true;
    },

    hideDialog() {
      this.dialogVisible = false;
    },

    initContent() {
      this.richObj.content = this.customContent.content;
    },
  },
  created() {},
  mounted() {
    this.initEditorHeight();
    this.initContent();
  },
  beforeDestroy() {},
  destroyed() {},
};
</script>

