<template>
  <div class="" style="padding: 0">
    <el-dialog
      class="resource-dialog"
      :title="resourceTitle"
      :visible.sync="visible"
      width="1010px"
      :close-on-click-modal="false"
      append-to-body
    >
      <el-tabs v-model="activeName">
        <el-tab-pane label="本地上传" name="local">
          <el-form
            ref="formUpload"
            :model="form_upload"
            v-loading="upload.isUploading"
            label-width="130px"
          >
            <el-form-item label="来源" prop="source">
              <el-radio-group v-model="form_upload.source" size="small">
                <el-radio-button label="local">本地上传</el-radio-button>
                <el-radio-button label="net">网络链接</el-radio-button>
              </el-radio-group>
            </el-form-item>
            <el-form-item v-show="showLocal" label="上传" prop="path">
              <el-upload
                ref="upload"
                list-type="picture-card"
                :accept="upload.accept"
                :limit="upload.limit"
                :multiple="upload.limit > 1"
                :action="upload.url"
                :headers="upload.headers"
                :data="upload.data"
                :file-list="upload.fileList"
                :before-upload="handleFileBeforeUpload"
                :on-progress="handleFileUploadProgress"
                :on-success="handleFileUploadSuccess"
                :on-error="handleFileUploadError"
                :on-exceed="handleFileUloadExceed"
                :auto-upload="false"
              >
                <i class="el-icon-plus"></i>
                <div slot="tip" class="el-upload__tip">
                  {{ ("点击上传", [upload.accept, fileSizeName]) }}
                </div>
              </el-upload>
            </el-form-item>
            <el-form-item v-show="showNet" label="网络链接" prop="path">
              <el-input
                v-model="form_upload.path"
                size="small"
                placeholder="http(s)://"
              ></el-input>
            </el-form-item>
          </el-form>
        </el-tab-pane>
      </el-tabs>
      <div slot="footer" class="dialog-footer">
        <el-button
          type="primary"
          :loading="upload.isUploading"
          @click="handleOk"
          >确定</el-button
        >
        <el-button @click="handleCancel">取消</el-button>
      </div>
    </el-dialog>
  </div>
</template>
<script>
import {
  isImage,
  getFileSvgIconClass,
} from "@/components/UEditorPlus/utils/chestnut.js";
import { getToken } from "@/components/UEditorPlus/utils/auth.js";
export default {
  name: "CMSResourceDialog",
  props: {
    open: {
      type: Boolean,
      default: false,
      required: true,
    },
    rtype: {
      type: String,
      required: false,
      default: "file",
    },
    uploadLimit: {
      type: Number,
      default: 1,
      required: false,
    },
  },
  data() {
    return {
      visible: false,
      activeName: "local",
      // siteId: this.$cache.local.get("CurrentSite"),
      form_upload: {
        source: "local",
        tags: [],
      },
      tagInputVisible: false,
      tagInputValue: "",
      // 上传参数
      upload: {
        isUploading: false, // 上传按钮loading
        accept: ".jpg,.png,.mp3,.mp4,.flv,.pdf", // 文件类型限制
        acceptSize: 20 * 1024 * 1024,
        limit: this.uploadLimit, // 文件数限制
        headers: { Authorizationsys: getToken() },
        url: "http://36.111.69.56:9010/tlxx-modules-annex/annexAction/upload",
        // url: process.env.VUE_APP_BASE_API + "/tlxx-modules-annex/annexAction/upload", // 上传的地址
        fileList: [], // 上传的文件列表
        data: {}, // 附带参数
      },
      uploadedCount: 0, // 已上传文件数量
      results: [], // 返回的上传/选择的文件结果

      loadingList: false,
      resourcesLoaded: false,
      resourceList: [],
      resourceTotal: 0,
      filterQuery: {
        pageNum: 1,
        pageSize: 10,
        resourceType: this.rtype,
        owner: false,
        name: undefined,
      },
      dateRange: [],
    };
  },
  computed: {
    showLocal() {
      return this.form_upload.source == "local";
    },
    showNet() {
      return this.form_upload.source == "net";
    },
    fileSizeName() {
      return this.upload.acceptSize / 1024 / 1024 + " MB";
    },
    resourceTitle() {
      if (this.rtype == "file") {
        return "上传文件";
      } else if (this.rtype == "video") {
        return "上传视频";
      } else if (this.rtype == "image") {
        return "上传图片";
      } else {
        return "素材库";
      }
    },
  },
  watch: {
    open(newVal) {
      this.visible = newVal;
    },
    visible(newVal) {
      if (!newVal) {
        this.noticeClose();
      } else {
        this.upload.isUploading = false;
        this.uploadedCount = 0;
      }
    },
    rtype(newVal) {
      this.loadResourceTypes();
    },
  },
  methods: {
    isImageResource(src) {
      return isImage(src);
    },
    getResourceFileIconClass(path) {
      return getFileSvgIconClass(path);
    },

    handleDeleteTag(tag) {
      this.form_upload.tags.splice(this.form_upload.tags.indexOf(tag), 1);
    },
    showTagInput() {
      this.tagInputVisible = true;
      this.$nextTick((_) => {
        this.$refs.tagInput.$refs.input.focus();
      });
    },

    loadResourceTypes() {
      let fileData = [
        {
          id: "audio",
          accepts: "mp3,wav,wma,ogg,aiff,aac,flac,mid",
          name: "音频",
        },
        {
          id: "video",
          accepts: "mp4,mpg,mpeg,rmvb,rm,avi,wmv,mov,flv",
          name: "视频",
        },
        {
          id: "image",
          accepts: "jpg,jpeg,gif,png,ico,webp",
          name: "图片",
        },
        {
          id: "file",
          accepts:
            "bmp,gif,jpg,jpeg,png,webp,psd,ai,tif,tiff,doc,docx,xls,xlsx,ppt,pptx,pdf,fla,swf,js,css,shtml,html,htm,txt,ttf,eot,mp4,avi,rmvb,mpg,flv,mpeg,rm,mov,wmv,wmp,mp3,wma,wav,ogg,rar,zip,gz,bz2,z,iso,cab,jar",
          name: "文件",
        },
      ];
      fileData.some((item) => {
        if (item.id == this.rtype) {
          this.upload.accept = "." + item.accepts.replaceAll(",", ",.");
          return true;
        }
        return false;
      });
    },

    handleFileBeforeUpload(file) {
      if (this.upload.acceptSize > 0 && file.size > this.upload.acceptSize) {
        this.$message.error("上传文件大小不能超过", [this.fileSizeName]);
        return false;
      }
      return true;
    },
    handleFileUloadExceed(files, fileList) {
      this.$modal.msgWarning("上传文件数量不能超过", [this.upload.limit]);
    },
    handleFileUploadProgress(event, file, fileList) {
      this.upload.isUploading = true;
    },
    handleFileUploadSuccess(response, file, fileList) {
      this.onFileUploaded(
        response.code == 1,
        fileList,
        response.code == 1 ? response.data : response.message
      );
    },
    handleFileUploadError(err, file, fileList) {
      this.onFileUploaded(false, fileList, "Upload failed.");
    },
    onFileUploaded(isSuccess, fileList, result) {
      console.log(this.rtype, "rtype");
      console.log(isSuccess, fileList, result);
      if (isSuccess) {
        this.uploadedCount++;
        this.results.push({
          path: result.address,
          name: result.name,
          src: result.url,
          width: result.width,
          height: result.height,
          fileSize: result.fileSize,
          fileSizeName: result.fileSizeName,
          resourceType: this.rtype,
        });
      } else {
        this.$modal.msgError(result);
      }
      if (this.uploadedCount == fileList.length) {
        this.noticeOk();
        this.upload.isUploading = false;
      }
    },
    handleOk() {
      console.log(this.activeName, this.form_upload.source);
      if (this.activeName === "local") {
        if (this.form_upload.source === "local") {
          Object.keys(this.form_upload).forEach(
            (key) => (this.upload.data[key] = this.form_upload[key])
          );
          this.$refs.upload.submit();
        } else {
          const url = this.form_upload.path;
          if (
            !url ||
            (!url.startsWith("http://") && !url.startsWith("https://"))
          ) {
            this.$modal.msgError(
              "资源外链不能为空且必须是http://或https://开头的网络地址"
            );
            return;
          }
          const name = url.substring(url.lastIndexOf("/") + 1);
          this.results.push({
            path: url,
            name: name,
            src: url,
            width: 0,
            height: 0,
            fileSize: 0,
            fileSizeName: "0",
            resourceType: "unknown",
            net: true,
          });
          this.noticeOk();
        }
      }

      // else {
      //   this.resourceList.forEach((item)=>{
      //     if (item.selected) {
      //       this.results.push({
      //         path: item.internalUrl,
      //         name: item.name,
      //         src: item.src,
      //         width: item.width,
      //         height: item.height,
      //         fileSize: item.fileSize,
      //         fileSizeName: item.fileSizeName,
      //         resourceType: item.resourceType
      //       });
      //     }
      //   });
      //   if (this.results.length == 0) {
      //     this.$modal.msgError("请先选择至少一条记录");
      //     return;
      //   }
      //   this.noticeOk();
      // }
    },
    handleCancel() {
      this.visible = false;
    },
    noticeOk() {
      if (this.visible) {
        this.$emit("ok", this.results);
        this.visible = false;
      }
    },
    noticeClose() {
      if (!this.visible) {
        this.$emit("update:open", false);
        this.$emit("close");
        this.reset();
      }
    },
    reset() {
      this.activeName = "local";
      this.form_upload = { source: "local", tags: [] };
      (this.tagInputVisible = false),
        (this.tagInputValue = ""),
        (this.upload.fileList = []);
      this.upload.data = {};
      this.uploadedCount = 0;
      this.results = [];
      this.resourcesLoaded = false;
      this.resourceList = [];
      this.resourceTotal = 0;
      this.filterQuery.pageNum = 1;
      this.filterQuery.owner = false;
      this.filterQuery.name = undefined;
      this.dateRange = [];
    },
  },
};
</script>
